class InspectLoader:OpenSim.ConfigurationLoader {public OpenSim.OpenSimConfigSource Current=>m_config;public OpenSim.Framework.ConfigSettings Settings=>m_configSettings;public OpenSim.Framework.NetworkServersInfo Network=>m_networkServersInfo;public bool Read(IConfigSource s,string path){return (bool)typeof(OpenSim.ConfigurationLoader).GetMethod("ReadConfig",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(this,new object[]{new OpenSim.OpenSimConfigSource{Source=s},path});}public string Includes(IConfigSource s,List<string> sources){typeof(OpenSim.ConfigurationLoader).GetMethod("AddIncludes",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(this,new object[]{new OpenSim.OpenSimConfigSource{Source=s},sources});return string.Join(",",sources.Select(Program.Enc));}}
class Program {
 public static List<string> Trace=new();public static string ConfigDir,Env;public static InspectLoader Active;public static IConfigSource Argv;public static string FirstDll;public static bool HaveFirst;static string fault;static int nth,hit;static readonly Dictionary<string,object> LogLiterals=new();static readonly Dictionary<string,object> ProducerLiterals=new();public static bool RecordStartup;public static string Identity(string group,string value){string id=group+":"+value;if(ProducerLiterals.TryGetValue(id,out var old))return ReferenceEquals(old,value)?"same":"different";ProducerLiterals[id]=value;return "first";}public static void RecordKey(string key){if(RecordStartup)Trace.Add("key:"+Enc(key)+":"+Identity("key",key));}public static void Wrap(IConfigSource source){if(!RecordStartup)return;var c=source.Configs["Startup"];if(c!=null){source.Configs.Remove(c);source.Configs.Add(new StartupProxy(c));}}public static string LogIdentity(object value){var text=(string)value;if(LogLiterals.TryGetValue(text,out var old))return ReferenceEquals(value,old)?"same":"different";LogLiterals[text]=value;return "first";}
 public static string Dec(string s)=>s=="null"?null:s=="-"?"":new string(Enumerable.Range(0,s.Length/4).Select(i=>(char)Convert.ToUInt16(s.Substring(i*4,4),16)).ToArray());public static string Enc(string s)=>s==null?"null":s.Length==0?"-":string.Concat(s.Select(c=>((int)c).ToString("x4",CultureInfo.InvariantCulture)));
 public static void Hit(string p,params string[] args){Trace.Add(p+":"+string.Join(":",args.Select(Enc)));if(fault=="mutate_source"&&p=="log"&&args.Length>2&&args[2].StartsWith("[CONFIG]: Reading configuration file")&&Active.Current!=null)Active.Current.Source=null;if(p==fault&&++hit==nth)throw new InvalidOperationException("provider fault");}
 static string Error(Exception e){if(e is TargetInvocationException t)e=t.InnerException;return e.GetType().FullName+":"+Enc(e.Message)+":"+unchecked((uint)e.HResult)+":"+(e is ArgumentException a?Enc(a.ParamName):"null");}
 static string Owner(IConfigSource source,InspectLoader l){if(ReferenceEquals(source,Argv))return "argv";if(ReferenceEquals(source,l.Current.Source))return "main";if(source is IniConfigSource ini&&ini.SavePath!=null)return "file:"+Enc(ini.SavePath);return source.GetType().FullName;}
 static string Snapshot(InspectLoader l){var o=new StringBuilder();o.Append(Enc(OpenSim.Application.iniFilePath)).Append('/');var settings=l.Settings;if(settings!=null)o.Append(Enc(settings.PhysicsEngine)).Append(',').Append(Enc(settings.MeshEngineName)).Append(',').Append(Enc(settings.ClientstackDll)).Append(',').Append(Enc(settings.LibrariesXMLFile));o.Append('/');if(l.Current!=null&&l.Current.Source==null)o.Append("nullsource");else if(l.Current!=null)foreach(IConfig c in l.Current.Source.Configs){o.Append(Enc(c.Name)).Append(':').Append(Owner(c.ConfigSource,l)).Append('[');var keys=c.GetKeys();var values=c.GetValues();for(int n=0;n<keys.Length;n++){var value=c.Get(keys[n]);o.Append(Enc(keys[n])).Append('=').Append(Enc(values[n])).Append('/').Append(Enc(value)).Append('@').Append(value!=null&&value.Length==0&&ReferenceEquals(value,string.Empty)?1:0).Append(',');}o.Append(']');}o.Append('/');var v=l.Network;if(v!=null)o.Append(string.Join(",",new[]{v.HttpListenerPort.ToString(),v.secureInventoryServer?"1":"0",v.isSandbox?"1":"0",v.HttpUsesSSL?"1":"0",Enc(v.HttpSSLCN),Enc(v.HttpSSLCertPath),Enc(v.HttpSSLCNCertPass),v.httpSSLPort.ToString(),v.ssl_listener?"1":"0",v.ssl_external?"1":"0",v.https_port.ToString(),Enc(v.cert_path),Enc(v.cert_pass),ReferenceEquals(v.cert_path,string.Empty)?"1":"0"}));o.Append('/').Append(HaveFirst&&ReferenceEquals(FirstDll,l.Settings?.ClientstackDll)?1:0).Append('/');foreach(var pair in Env.Split(',',StringSplitOptions.RemoveEmptyEntries)){var bits=pair.Split(':');var name=Dec(bits[0]);o.Append(Enc(name)).Append('=').Append(Enc(System.Environment.GetEnvironmentVariable(name))).Append(',');}return o.ToString();}
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;CultureInfo.CurrentUICulture=CultureInfo.InvariantCulture;string row;while((row=Console.ReadLine())!=null){var a=row.Split(' ');Trace=new();LogLiterals.Clear();ProducerLiterals.Clear();RecordStartup=a[0]=="K";ConfigDir=Dec(a[2]);Env=Dec(a[4]);fault=a[5];nth=int.Parse(a[6]);hit=0;FirstDll=null;HaveFirst=false;var l=new InspectLoader();Active=l;string result="ok";try{foreach(var op in Env.Split(',',StringSplitOptions.RemoveEmptyEntries)){var pair=op.Split(':');System.Environment.SetEnvironmentVariable(Dec(pair[0]),Dec(pair[1]));}var argv=new IniConfigSource(new StringReader(Dec(a[1])));Argv=argv;argv.Alias.AddAlias("On",true);argv.Alias.AddAlias("Yes",true);argv.Alias.AddAlias("Off",false);Wrap(argv);if(a[0]=="R")result=l.Read(argv,Dec(a[3]))?"1":"0";else if(a[0]=="I"){var list=Dec(a[3]).Split('\n',StringSplitOptions.RemoveEmptyEntries).ToList();result=l.Includes(argv,list);}else {l.LoadConfigSettings(argv,new EnvConfigSource(),out var settings,out var network);if(a[0]=="T"||a[0]=="K"){FirstDll=settings.ClientstackDll;HaveFirst=true;l=new InspectLoader();Active=l;Argv=new IniConfigSource(new StringReader(Dec(a[3])));Argv.Alias.AddAlias("On",true);Argv.Alias.AddAlias("Yes",true);Argv.Alias.AddAlias("Off",false);Wrap(Argv);l.LoadConfigSettings(Argv,new EnvConfigSource(),out settings,out network);}}}catch(Exception e){result=Error(e);}Console.WriteLine(result+"/"+Snapshot(l)+"/"+string.Join(";",Trace));}}
}
